const updateSensor = `-- name: UpdateSensor :one
UPDATE sigint_sensors
SET name = $1,
    slug = $2,
    description = $3,
    instructions = $4,
    mode = $5,
    enabled = $6,
    match_expression = $7,
    updated_at = clock_timestamp()
WHERE id = $8
  AND project_id = $9
  AND deleted IS FALSE
RETURNING id, project_id, name, slug, description, instructions, mode, match_expression, enabled, created_at, updated_at, deleted_at, deleted
`

type UpdateSensorParams struct {
	Name            string
	Slug            string
	Description     pgtype.Text
	Instructions    pgtype.Text
	Mode            string
	Enabled         bool
	MatchExpression string
	ID              uuid.UUID
	ProjectID       uuid.UUID
}

func (q *Queries) UpdateSensor(ctx context.Context, arg UpdateSensorParams) (SigintSensor, error) {
	row := q.db.QueryRow(ctx, updateSensor,
		arg.Name,
		arg.Slug,
		arg.Description,
		arg.Instructions,
		arg.Mode,
		arg.Enabled,
		arg.MatchExpression,
		arg.ID,
		arg.ProjectID,
	)
	var i SigintSensor
	err := row.Scan(
		&i.ID,
		&i.ProjectID,
		&i.Name,
		&i.Slug,
		&i.Description,
		&i.Instructions,
		&i.Mode,
		&i.MatchExpression,
		&i.Enabled,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
		&i.Deleted,
	)
	return i, err
}

